{"command":["bash","-lc","python3 - <<'PY'
import json,glob,os
base='/root/projects/open_source/zero/B96DF826-4BB2-4B62-97AB-6D84254C53D7/Scenario-4/alerts'
alerts=[]
for f in sorted(glob.glob(os.path.join(base,'alerts_at_*.json'))):
    with open(f) as fp:
        data=json.load(fp)
    for a in data:
        if a.get('labels',{}).get('namespace')=='otel-demo':
            alerts.append(a)

names=set(a['labels']['alertname'] for a in alerts)
print('alert names',names)
# count firing per name
from collections import Counter
c=Counter()
for a in alerts:
    if a['state']=='firing':
        c[a['labels']['alertname']]+=1
print('firing counts',c)
PY"]}

